def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_def = 0
    my_def = 0
    last_m, last_o = history[-1]
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1
    if opp_def > n * 0.4:
        return 'D'
    if last_o == 'D':
        if opp_def > n * 0.3:
            return 'D'
        return 'C'
    if opp_def == 0:
        if my_def == 0:
            if n == 10:
                return 'D'
            return 'C'
        else:
            last_def = -1
            for i in range(n - 1, -1, -1):
                if history[i][0] == 'D':
                    last_def = i
                    break
            if last_def != -1 and n - 1 - last_def >= 10 and n < 99:
                return 'D'
            return 'C'
    return 'C'
